s32 menuPocketColognCursor(tagWINDOW_WORK *w){POCKET_COLOGNE_ARG *p=(POCKET_COLOGNE_ARG*)w->parameters[0];u16 keys=windowGetKeyRepeat();s32 count=p->count;s16 old=w->selected;if(keys&2){s8 next=old+1;if(next>=count)next=count-1;w->selected=next;}if(keys&1){s8 next=w->selected-1;if(next<0)next=0;w->selected=next;}if(old!=w->selected)menuSubCursorAnimeStart();return 0;}
